static SharedPreferences prefs(Context c){return c.getSharedPreferences("words",0);}
static int current(Context c){return Math.max(0,Math.min(WORDS.length-1,prefs(c).getInt("index",0)));}
static void refresh(Context c,boolean next){SharedPreferences p=prefs(c);int i=current(c);if(next){int level=p.getInt("level",0);Set<String> learned=p.getStringSet("learned",Collections.emptySet());for(int k=1;k<=WORDS.length;k++){int j=(i+k)%WORDS.length;if((level==0||Integer.parseInt(WORDS[j][0])==level-1)&&(!p.getBoolean("skip",true)||!learned.contains(WORDS[j][1]))){i=j;break;}}p.edit().putInt("index",i).putLong("last",System.currentTimeMillis()).apply();}AppWidgetManager m=AppWidgetManager.getInstance(c);for(int id:m.getAppWidgetIds(new ComponentName(c,WordWidget.class))){RemoteViews r=new RemoteViews(c.getPackageName(),R.layout.word_widget);r.setTextViewText(R.id.english,WORDS[i][1].substring(0,1).toUpperCase(java.util.Locale.ENGLISH)+WORDS[i][1].substring(1));r.setTextViewText(R.id.turkish,WORDS[i][2]);int size=p.getInt("size",30);r.setTextViewTextSize(R.id.english,TypedValue.COMPLEX_UNIT_SP,Math.min(size,WORDS[i][1].length()>12?22:WORDS[i][1].length()>9?26:size));r.setTextViewTextSize(R.id.turkish,TypedValue.COMPLEX_UNIT_SP,p.getInt("trsize",12));int color=p.getInt("color",0);r.setTextColor(R.id.english,new int[]{0xffF6D477,0xffFFFFFF,0xffFFF0CD}[color]);r.setTextColor(R.id.turkish,color==1?Color.WHITE:0xffFFF0CD);int font=p.getInt("font",0);if(font!=0){r.setViewVisibility(R.id.english,android.view.View.GONE);r.setViewVisibility(R.id.altenglish,android.view.View.VISIBLE);r.setTextViewText(R.id.altenglish,WORDS[i][1]);r.setTextViewTextSize(R.id.altenglish,TypedValue.COMPLEX_UNIT_SP,Math.min(size,WORDS[i][1].length()>12?22:size));r.setTextColor(R.id.altenglish,new int[]{0xffF6D477,0xffFFFFFF,0xffFFF0CD}[color]);}else{r.setViewVisibility(R.id.english,android.view.View.VISIBLE);r.setViewVisibility(R.id.altenglish,android.view.View.GONE);}r.setOnClickPendingIntent(R.id.widget_root,PendingIntent.getBroadcast(c,0,new Intent(c,WordWidget.class).setAction("com.wordlock.NEXT"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));m.updateAppWidget(id,r);}}
public void onUpdate(Context c,AppWidgetManager m,int[] ids){refresh(c,false);}public void onReceive(Context c,Intent i){super.onReceive(c,i);if("com.wordlock.NEXT".equals(i.getAction()))refresh(c,true);}
